package local.usbcontrol;

import java.io.IOException;
import java.util.*;

/** Fixed allowlist; never accepts a package name from editable UI. */
final class SystemApps {
    interface Runner { String run(String command) throws Exception; }
    static final class Entry {
        final String name, pkg;
        final boolean installed;
        Entry(String name,String pkg,boolean installed){this.name=name;this.pkg=pkg;this.installed=installed;}
        String label(){return name+"\n"+pkg;}
    }
    private static final String[][] TARGETS={
        {"快应用","com.miui.hybrid"},
        {"内容中心","com.miui.newhome"},
        {"内容中心","com.miui.contentcenter"},
        {"浏览器","com.android.browser"},
        {"系统广告 adsolution","com.miui.systemAdSolution"}
    };
    private static String user(int user){if(user<0)throw new IllegalArgumentException("用户编号异常");return Integer.toString(user);}
    private static Set<String> packages(String output)throws IOException {
        Set<String> result=new HashSet<>();
        for(String line:output.split("\\r?\\n")){
            if(line.trim().isEmpty())continue;
            if(!line.matches("package:[a-zA-Z0-9_.]+"))throw new IOException("应用列表读取异常："+line);
            result.add(line.substring(8));
        }
        return result;
    }
    static List<Entry> scan(Runner runner,int user)throws Exception {
        String uid=user(user);
        Set<String> system=packages(runner.run("pm list packages -s -u --user "+uid));
        Set<String> installed=packages(runner.run("pm list packages --user "+uid));
        List<Entry> result=new ArrayList<>();
        for(String[] target:TARGETS)if(system.contains(target[1]))result.add(new Entry(target[0],target[1],installed.contains(target[1])));
        return result;
    }
    static String command(String pkg,int user,boolean restore){
        boolean known=false;for(String[] t:TARGETS)if(t[1].equals(pkg))known=true;
        if(!known)throw new IllegalArgumentException("未知应用");
        return restore?"cmd package install-existing --user "+user(user)+" "+pkg:
            "pm uninstall --user "+user(user)+" "+pkg;
    }
    static String apply(Runner runner,int user,List<Entry> selection,boolean restore)throws Exception {
        if(selection.isEmpty())throw new IllegalArgumentException("请先勾选应用");
        // Re-read before mutation: stale dialogs and caller-created entries confer no eligibility.
        List<Entry> current=scan(runner,user);
        StringBuilder report=new StringBuilder();Set<String> seen=new HashSet<>();
        for(Entry selected:selection){
            if(!seen.add(selected.pkg))continue;
            Entry actual=null;for(Entry e:current)if(e.pkg.equals(selected.pkg))actual=e;
            if(actual==null){report.append(selected.name).append("：跳过（未识别为受支持的系统应用）\n");continue;}
            if(actual.installed==restore){report.append(actual.name).append(restore?"：已安装，跳过\n":"：已卸载，跳过\n");continue;}
            try {
                String output=runner.run(command(actual.pkg,user,restore));
                boolean installed=packages(runner.run("pm list packages --user "+user(user)+" "+actual.pkg)).contains(actual.pkg);
                if(installed!=restore)throw new IOException("状态读回未符合预期；"+output);
                report.append(actual.name).append(restore?"：已恢复应用（不恢复已删除的数据）":"：已卸载（不保留应用数据）").append("\n");
            }catch(Exception e){report.append(actual.name).append("：操作未完成，").append(e.getMessage()).append("\n");}
        }
        return report.toString().trim();
    }
}

package local.usbcontrol;

import java.io.*;
import java.util.concurrent.*;

final class Root {
    static String quote(String s) { return "'" + s.replace("'", "'\\''") + "'"; }
    static String run(String command) throws Exception {
        return run(command,35);
    }
    static String run(String command,int timeoutSeconds) throws Exception {
        // No shell input comes from editable UI: density is numeric; names are constants.
        Process p;
        try { p = new ProcessBuilder("su", "-c", command).redirectErrorStream(true).start(); }
        catch(IOException e) { throw new IOException("未检测到 Root，请安装并授权超级用户管理器"); }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        java.util.concurrent.atomic.AtomicBoolean truncated=new java.util.concurrent.atomic.AtomicBoolean();
        Thread reader = new Thread(() -> { try(InputStream in=p.getInputStream()) {
            byte[] b = new byte[4096]; int n;
            while((n=in.read(b))!=-1) synchronized(out) { if(out.size()+n<=262144) out.write(b,0,n); else truncated.set(true); }
        } catch(IOException ignored) {} });
        reader.setDaemon(true); reader.start();
        try {
        if(!p.waitFor(timeoutSeconds,TimeUnit.SECONDS)) { p.destroyForcibly(); throw new IOException("Root 请求超时，请检查超级用户授权"); }
        reader.join(1000);
        if(reader.isAlive())throw new IOException("Root 输出流尚未结束，请重试");
        if(truncated.get())throw new IOException("Root 返回内容超限，已停止解析");
        String result;
        synchronized(out){result=out.toString("UTF-8");}
        if(p.exitValue()!=0) throw new IOException("Root 命令失败 ("+p.exitValue()+")\n"+result);
        return result.trim();
        }finally{p.getInputStream().close();p.getOutputStream().close();p.getErrorStream().close();if(p.isAlive())p.destroyForcibly();}
    }
    static String section(String s,String tag) {
        String token="__"+tag+"__\n";
        int i=s.indexOf(token);
        if(i<0) return "";
        i+=token.length(); int end=s.indexOf("\n__",i);
        return (end<0?s.substring(i):s.substring(i,end)).trim();
    }
    static final String SNAPSHOT = "set -e; printf '__UID__\\n'; id -u; " +
        "printf '__ADB__\\n'; settings get global adb_enabled; " +
        "printf '__DEV__\\n'; settings get global development_settings_enabled; " +
        "printf '__SIZE__\\n'; wm size; printf '__DENSITY__\\n'; wm density; " +
        "printf '__GLOBAL__\\n'; v=$(settings get global adb_install_enabled); printf 'adb_install_enabled=%s\\n' \"$v\"; "+
        "printf '__SECURE__\\n'; v=$(settings get secure adb_install_enabled); printf 'adb_install_enabled=%s\\n' \"$v\"; "+
        "printf '__SYSTEM__\\n'; v=$(settings get system adb_install_enabled); printf 'adb_install_enabled=%s\\n' \"$v\"; "+
        "printf '__MIUI__\\n'; "+UsbInstall.PROBE;
    static void validate(String s)throws IOException {
        for(String tag:new String[]{"UID","ADB","DEV","SIZE","DENSITY","GLOBAL","SECURE","SYSTEM"})
            if(!s.contains("__"+tag+"__\n"))throw new IOException("系统状态返回不完整："+tag);
        if(!"0".equals(section(s,"UID")))throw new IOException("请授予 Root 权限");
        for(String tag:new String[]{"ADB","DEV"})if(!section(s,tag).matches("null|[0-9]{1,9}"))throw new IOException("系统状态值异常："+tag);
        int[] size=Logic.size(section(s,"SIZE"));if(size[0]<=0||size[1]<=0)throw new IOException("屏幕尺寸读取失败");
        DensitySession.previous(section(s,"DENSITY"));
    }
}

package local.usbcontrol;

import java.io.IOException;

/** Vendor adapters change only the existing USB-install setting, never verification policy. */
final class UsbInstall {
    static final String MIUI="miui";
    private static final String URI="content://com.miui.securitycenter.remoteprovider";
    private static final String KEY="security_adb_install_enable";
    private static final String CALL="content call --uri "+URI+" --method callPreference --arg ";
    private static final String EXTRAS=" --extra type:i:1 --extra key:s:"+KEY;
    static final String ENABLE="am start --user current -n com.miui.securitycenter/com.miui.permcenter.install.AdbInstallVerifyActivity -a com.miui.securitycenter.action.ADB_INSTALL_VERIFY";
    static final String PROBE="if [ -n \"$(getprop ro.miui.ui.version.name)\" ]; then "+
        CALL+"CONTAIN_KEY"+EXTRAS+" 2>/dev/null || true; "+
        CALL+"GET"+EXTRAS+" --extra default:b:false 2>/dev/null || true; "+
        "cmd package resolve-activity --brief -a com.miui.securitycenter.action.ADB_INSTALL_VERIFY -p com.miui.securitycenter 2>/dev/null || true; fi";

    static boolean validBackend(String backend){return backend!=null&&backend.matches("global|secure|system|miui");}
    static String backend(String snapshot){
        if(Logic.miuiInstallState(Root.section(snapshot,"MIUI"))!=null)return MIUI;
        return Logic.installNamespace(Root.section(snapshot,"GLOBAL"),Root.section(snapshot,"SECURE"),Root.section(snapshot,"SYSTEM"));
    }
    static String state(String snapshot,String backend){
        if(MIUI.equals(backend))return Logic.miuiInstallState(Root.section(snapshot,"MIUI"));
        if(!validBackend(backend))return null;
        java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?m)^adb_install_enabled=([01])\\r?$").matcher(Root.section(snapshot,backend.toUpperCase(java.util.Locale.ROOT)));
        return m.find()?m.group(1):null;
    }
    static String read(String backend)throws Exception {
        if(!validBackend(backend))throw new IOException("USB 安装接口未识别");
        String value=MIUI.equals(backend)?Logic.miuiInstallState(Root.run(PROBE)):Root.run("settings get "+backend+" adb_install_enabled");
        if(value==null||!value.matches("[01]"))throw new IOException("USB 安装状态读取失败");
        return value;
    }
    static String writeCommand(String backend,boolean on){
        if(!validBackend(backend))throw new IllegalArgumentException("USB 安装接口异常");
        if(MIUI.equals(backend))return on?ENABLE:CALL+"SET"+EXTRAS+" --extra value:b:false";
        return "settings put "+backend+" adb_install_enabled "+(on?"1":"0");
    }
    static String readSnapshot(String snapshot,String backend)throws Exception {
        if(!validBackend(backend))throw new IOException("USB 安装接口未识别");
        if(MIUI.equals(backend)){
            String probe=Root.run(PROBE);
            if(Logic.miuiInstallState(probe)==null)throw new IOException("USB 安装接口已变化，请刷新后重试");
            return Logic.replaceSection(snapshot,"MIUI",probe);
        }
        return Logic.replaceSection(snapshot,backend.toUpperCase(java.util.Locale.ROOT),"adb_install_enabled="+read(backend));
    }
    static String toggleCommand(String backend,boolean on){
        if(!validBackend(backend))throw new IllegalArgumentException("USB 安装接口异常");
        if(MIUI.equals(backend)){
            String guard="[ \"$("+CALL+"CONTAIN_KEY"+EXTRAS+")\" = 'Result: Bundle[{CONTAIN_KEY=true}]' ]";
            return "set -e; "+guard+"; "+writeCommand(backend,on)+(on?"":"; "+PROBE);
        }
        return "set -e; old=$(settings get "+backend+" adb_install_enabled); case \"$old\" in 0|1) ;; *) exit 2;; esac; "+
            writeCommand(backend,on)+"; settings get "+backend+" adb_install_enabled";
    }
    static String toggleSnapshot(String snapshot,String backend,boolean on)throws Exception {
        String output=Root.run(toggleCommand(backend,on));
        if(MIUI.equals(backend)&&on){
            if(output.contains("Error:")||output.contains("Exception"))throw new IOException("系统 USB 安装流程启动失败");
            return snapshot; // Await real provider readback on return, never assume enabled.
        }
        String value=MIUI.equals(backend)?Logic.miuiInstallState(output):output;
        if(!(on?"1":"0").equals(value))throw new IOException("系统未接受 USB 安装变更");
        return Logic.replaceSection(snapshot,MIUI.equals(backend)?"MIUI":backend.toUpperCase(java.util.Locale.ROOT),
            MIUI.equals(backend)?output:"adb_install_enabled="+value);
    }
    static String verifyCommand(String backend,String value){
        if(!validBackend(backend)||!value.matches("[01]"))throw new IllegalArgumentException("USB 安装恢复记录异常");
        String get=MIUI.equals(backend)?CALL+"GET"+EXTRAS+" --extra default:b:false":"settings get "+backend+" adb_install_enabled";
        String expected=MIUI.equals(backend)?"Result: Bundle[{"+KEY+"="+("1".equals(value)?"true":"false")+"}]":value;
        return "[ \"$("+get+")\" = "+Root.quote(expected)+" ]";
    }
    static String restoreCommand(String backend,String value){
        String verify=verifyCommand(backend,value);
        if(MIUI.equals(backend)&&"1".equals(value))return "("+verify+" || { "+ENABLE+"; printf '请完成系统 USB 安装确认后，再重试恢复\\n'; "+verify+"; })";
        return "("+writeCommand(backend,"1".equals(value))+" && "+verify+")";
    }
}

package local.usbcontrol;

import android.content.Context;
import java.io.*;

final class WallpaperLoop {
    static final String DIRECTORY="/sdcard/Android/data/com.android.thememanager/files/MIUI/.videowallpaper";
    static synchronized String run(Context context, boolean undo) throws Exception {
        if(android.os.Process.myUid()/100000!=0)throw new IOException("此壁纸目录仅适配手机主用户，请在主用户中使用轻控");
        File dir=new File(context.getFilesDir(),"wallpaper-loop");
        if(!dir.isDirectory()&&!dir.mkdir())throw new IOException("壁纸任务目录创建失败");
        File expected=new File(context.getFilesDir().getCanonicalFile(),"wallpaper-loop");
        if(!dir.getCanonicalFile().equals(expected))throw new IOException("壁纸任务目录异常，请检查 App 私有目录");
        File script=new File(dir,"wallpaper.sh");
        try(InputStream in=context.getResources().openRawResource(R.raw.wallpaper);
            ByteArrayOutputStream out=new ByteArrayOutputStream()) {
            byte[] b=new byte[4096];int n;
            while((n=in.read(b))!=-1)out.write(b,0,n);
            SafeFiles.write(script,out.toByteArray());
        }
        return Root.run("sh "+Root.quote(script.getAbsolutePath())+" "+Root.quote(DIRECTORY)+" "+Root.quote(dir.getAbsolutePath())+" "+(undo?"undo":"apply"),600);
    }
}
